void count_words_and_lines(const char *text, int *words, int *lines) {
    *words = 0; *lines = 0;
    int in_word = 0;
    for (; *text; text++) {
        if (*text == '\n') (*lines)++;
        if (isspace((unsigned char)*text)) in_word = 0;
        else if (!in_word) { in_word = 1; (*words)++; }
    }
}

