void kv_put(const char *k, const char *v) {
    if (db_count < MAX_ENTRIES) {
        strncpy(db[db_count].key, k, 31);
        strncpy(db[db_count].val, v, 31);
        db_count++;
    }
}

const char *kv_get(const char *k) {
    for (int i = 0; i < db_count; i++)
        if (strcmp(db[i].key, k) == 0) return db[i].val;
    return NULL;
}

